-- Bertox event trash: 3m50s -> 5m50s. Test already uses 350 seconds.
-- Preserve variance and independently modified rows.
UPDATE spawn2
SET respawntime = 350
WHERE zone = 'codecay'
  AND respawntime = 230
  AND id IN (369228, 369229, 369230, 369231, 369232, 369233, 369234, 369235, 369236, 369237, 369238, 369239, 369240, 369242, 369243, 369245, 369246, 369247, 369248, 369249, 369250, 369251, 369252, 369253, 369254, 369256, 369258, 369259, 369261, 369262, 369263, 369264);

SELECT id, respawntime, variance FROM spawn2
WHERE zone = 'codecay' AND id IN (369228, 369229, 369230, 369231, 369232, 369233, 369234, 369235, 369236, 369237, 369238, 369239, 369240, 369242, 369243, 369245, 369246, 369247, 369248, 369249, 369250, 369251, 369252, 369253, 369254, 369256, 369258, 369259, 369261, 369262, 369263, 369264) ORDER BY id;
